def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[0][1] == 'C' and history[1][1] == 'C':
            return 'C'
        return 'C' if history[1][1] == 'C' and history[0][1] == 'D' else 'D'
    if n == 3:
        if history[-1][1] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
            return 'D'
        return 'C' if history[-1][1] == 'C' else 'D'
    if n == 4:
        return 'C' if history[-1][1] == 'C' or history[-2][1] == 'C' else 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opD = op.count('D')
    opC = n - opD

    if opD == 0:
        return 'C' if n < 96 else 'D'
    if opD == n:
        if n < 10:
            return 'D'
        if op[-5:].count('C') > 0:
            return 'C'
        return 'D'

    rr = op[-1]
    if rr == 'C':
        if opC >= n - opD * 2 and op[-2:] == ['C', 'C']:
            return 'C'
        if op[-3:] == ['C', 'C', 'C']:
            return 'C'
        if opD * 3 <= n and op[-1] == 'C':
            return 'C'
        if op[-1] == 'C' and op[-2] == 'C':
            return 'C'
        return 'C'

    d_run = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        d_run += 1
        i -= 1

    if d_run == 1:
        if opD * 4 <= n:
            return 'D'
        if n >= 8 and op[-8:].count('C') >= 6:
            return 'D'
        return 'D'

    if d_run == 2:
        if opD * 3 <= n:
            return 'D'
        if n >= 6 and op[-6:].count('C') >= 4:
            return 'D'
        return 'D'

    if d_run >= 3:
        if n >= 12 and opD * 2 <= n:
            return 'C' if d_run == 3 else 'D'
        return 'D'
    return 'C'
